import React from 'react';
import { getContext } from '@fiverr-private/fiverr_context';
import { Container, Stack } from '@fiverr-private/layout_components';
import { fileSizeFormat } from '@fiverr-private/localization';
import { Text, type TextProps } from '@fiverr-private/typography';
import { findChildByType, excludeChildrenByType } from '@fiverr-private/ui_utils';
import type { Types } from '@fiverr-private/theme';
import Asset from '../../Asset';
import { useActiveState } from '../../hooks/useActiveState';
import RemoveButton from '../RemoveButton';
import type { AttachmentProps } from '../types';
import { renderAttachmentsChildren } from '../../utils';

const AttachmentListItem = ({
  error,
  showPreview,
  onRemove,
  onClick,
  hasError,
  name,
  fileSize: fileSizeProp,
  url,
  children,
  variant,
  theme,
  dataTrackTag,
  dataTrackValue,
}: AttachmentProps) => {
  const { isTouch } = getContext();
  const { isActive, handleMouseEnter, handleMouseLeave, handleFocus, handleBlur } = useActiveState();
  const retryBtn = findChildByType(children, 'AttachmentRetryBtn');
  const restChildren = excludeChildrenByType(children, 'AttachmentRetryBtn');
  const fileSize = fileSizeProp
    ? fileSizeFormat({
        bytes: fileSizeProp,
        options: {
          maximumFractionDigits: 0,
        },
      })
    : undefined;

  const ellipsisPros: TextProps = {
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
  };

  const getBackgroundColor = (isActive: boolean): Types.BackgroundColor | undefined => {
    if (theme === 'dark') {
      return isActive ? 'white_20' : 'white_10';
    }

    return isActive ? 'grey_100' : undefined;
  };

  return (
    <Stack
      gap="6"
      paddingY="1.5"
      paddingX="2"
      justifyContent="spaceBetween"
      borderRadius="sm"
      alignItems="center"
      onFocus={handleFocus}
      onBlur={handleBlur}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      tabIndex={0}
      onClick={onClick}
      backgroundColor={getBackgroundColor(isActive)}
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
    >
      <Stack gap="4" overflow="hidden">
        <Asset name={name} url={url} hasError={hasError} variant={variant} showPreview={showPreview} theme={theme} />
        <Stack direction="column" gap="0" overflow="hidden">
          {!(isTouch && hasError) && (
            <Text color={theme === 'dark' ? 'white' : undefined} size="b_sm" fontWeight="semibold" {...ellipsisPros}>
              {name}
            </Text>
          )}
          <Text size="b_sm" color={hasError ? 'validationError' : 'bodySecondary'} {...ellipsisPros}>
            {hasError ? error : fileSize?.toLocaleUpperCase()}
          </Text>
          {hasError && isTouch && renderAttachmentsChildren(retryBtn, { variant, theme })}
        </Stack>
      </Stack>
      <Stack flexShrink={0} gap="2">
        {hasError && isActive && !isTouch && renderAttachmentsChildren(retryBtn, { variant, theme })}
        <Container hidden={!isActive || isTouch}>
          {renderAttachmentsChildren(restChildren, { variant, theme })}
        </Container>
        {(isActive || isTouch) && <RemoveButton variant={variant} onClick={onRemove} theme={theme} />}
      </Stack>
    </Stack>
  );
};

AttachmentListItem.displayName = 'AttachmentListItem';
export default AttachmentListItem;
