import React from 'react';
import { IconButton, TextButton } from '@fiverr-private/button';
import { I18n, translate } from '@fiverr-private/i18n-react';
import { getContext } from '@fiverr-private/fiverr_context';
import { RefreshIcon } from '@fiverr-private/visuals';
import type { AttachmentRetryBtnProps } from './types';

const AttachmentRetryBtn = ({
  onClick,
  variant,
  dataTrackTag = 'attachment_retry_button',
  dataTrackValue,
}: AttachmentRetryBtnProps) => {
  const { isTouch } = getContext();

  if (variant !== 'list' && !isTouch) {
    return (
      <IconButton
        dataTrackTag={dataTrackTag}
        dataTrackValue={dataTrackValue}
        onClick={onClick}
        aria-label={translate<string>('attachments.retry')}
        intent="primary"
        size="xs"
      >
        <RefreshIcon />
      </IconButton>
    );
  }

  return (
    <TextButton
      alignSelf={isTouch && variant === 'list' ? 'flexStart' : undefined}
      onClick={onClick}
      size="sm"
      variant={variant === 'list' ? 'default' : 'underline'}
    >
      <I18n k="attachments.retry"></I18n>
    </TextButton>
  );
};

AttachmentRetryBtn.displayName = 'AttachmentRetryBtn';
AttachmentRetryBtn.id = 'AttachmentRetryBtn';
export default AttachmentRetryBtn;
