import { getContext } from '@fiverr-private/fiverr_context';
import { useConst, useElementSize } from '@fiverr-private/hooks';
import { setFiverrContext } from '@fiverr-private/storybook_helpers';

const mobileContext = {
    userAgent:
        'Mozilla/5.0 (Linux; U; Android 4.4.2; en-us; SCH-I535 Build/KOT49H) AppleWebKit/534.30 (KHTML, like Gecko) Version/4.0 Mobile Safari/534.30',
    isTouch: true,
    isMobile: true,
};

export const useSetMobileContext = (customContext = mobileContext) => {
    const { width } = useElementSize(window);
    const fiverrContext = useConst(() => getContext());

    if (width && width < 600) {
        setFiverrContext(customContext);
    } else {
        setFiverrContext(fiverrContext);
    }
};
