import React, { useState } from 'react';
import { Button, TextButton } from '@fiverr-private/button';
import { I18n, translate } from '@fiverr-private/i18n-react';
import { Stack } from '@fiverr-private/layout_components';
import { getContext } from '@fiverr-private/fiverr_context';
import {
  Modal,
  ModalBody,
  ModalCancelBtn,
  ModalContent,
  ModalFooter,
  ModalHeader,
  ModalTrigger,
} from '@fiverr-private/overlay';
import { RefreshIcon } from '@fiverr-private/visuals';
import type { AttachmentRetrieveBtnProps } from './types';

const AttachmentRetrieveBtn = ({
  onClick,
  variant,
  copies,
  setIsTooltipOpen,
  dataTrackTag = 'attachment_retrieve_button',
  dataTrackValue,
}: AttachmentRetrieveBtnProps) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { isTouch } = getContext();

  const handleModalOpen = () => {
    setIsModalOpen(true);
    setIsTooltipOpen?.(false);
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
    setIsTooltipOpen?.(true);
  };

  let buttonContent;
  if (variant !== 'list' && !isTouch) {
    buttonContent = (
      <Button
        dataTrackTag={dataTrackTag}
        dataTrackValue={dataTrackValue}
        aria-label={translate<string>('attachments.retrieve')}
        intent="primary"
        size="sm"
      >
        <RefreshIcon />
        <I18n k="attachments.retrieve"></I18n>
      </Button>
    );
  } else {
    const isWithCopies = copies?.retrieveButtonText;
    const buttonText = isWithCopies ? copies.retrieveButtonText() : <I18n k="attachments.retrieve"></I18n>;
    buttonContent = (
      <TextButton
        dataTrackTag={dataTrackTag}
        dataTrackValue={dataTrackValue}
        alignSelf={isTouch && variant === 'list' ? 'flexStart' : undefined}
        size="sm"
        variant={variant === 'list' && !isWithCopies ? 'default' : 'underline'}
      >
        {isWithCopies && <RefreshIcon />}
        {buttonText}
      </TextButton>
    );
  }

  return (
    <Modal isOpen={isModalOpen} onOpen={handleModalOpen} onClose={handleModalClose}>
      <ModalTrigger>{buttonContent}</ModalTrigger>
      <ModalContent dataTrackTag={'attachment_retrieve_modal'}>
        <ModalHeader>
          <I18n k="attachments.retrieveModal.title"></I18n>
        </ModalHeader>
        <ModalBody>
          <Stack style={{ display: 'inline' }} color="grey_1000">
            <I18n k="attachments.retrieveModal.description"></I18n>
          </Stack>
        </ModalBody>
        <ModalFooter>
          <ModalCancelBtn dataTrackTag="attachment_cancel_button" onClick={() => setIsModalOpen(false)}>
            <I18n k="attachments.retrieveModal.cancel"></I18n>
          </ModalCancelBtn>
          <Button
            dataTrackTag="attachment_submit_retrieve_button"
            onClick={(e) => {
              onClick?.(e);
              setIsModalOpen(false);
            }}
            intent="primary"
          >
            <I18n k="attachments.retrieveModal.submit"></I18n>
          </Button>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
};

AttachmentRetrieveBtn.displayName = 'AttachmentRetrieveBtn';
AttachmentRetrieveBtn.id = 'AttachmentRetrieveBtn';
export default AttachmentRetrieveBtn;
