import React from 'react';
import { Status, type StatusProps } from '@fiverr-private/data_display';
import { I18n } from '@fiverr-private/i18n-react';
import type { AttachmentStatusProps, AttachmentStatusType } from './types';

const ATTACHMENTS_CONFIG: {
  [key in Exclude<AttachmentStatusType, 'active'>]: { i18nKey: string; statusVariant: StatusProps['type'] };
} = {
  deleted: { i18nKey: 'attachments.statuses.deleted', statusVariant: 'error' },
  archived: { i18nKey: 'attachments.statuses.archived', statusVariant: 'neutral' },
  restore_in_progress: { i18nKey: 'attachments.statuses.restore_in_progress', statusVariant: 'info' },
};

const AttachmentStatus = ({ status, variant }: AttachmentStatusProps) => {
  if (variant !== 'single' || status === 'active') {
    return null;
  }

  return (
    <Status dataTrackTag="attachment_status" dataTrackValue={status} type={ATTACHMENTS_CONFIG[status].statusVariant}>
      <I18n k={ATTACHMENTS_CONFIG[status].i18nKey} />
    </Status>
  );
};

AttachmentStatus.displayName = 'AttachmentStatus';
AttachmentStatus.id = 'AttachmentStatus';
export default AttachmentStatus;
